import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:qr_flutter/qr_flutter.dart';

import 'package:evently_core/evently_core.dart';

/// Shows the participant's signed QR ticket. The payload is generated by the
/// getMyTicket callable; scanning it at the door triggers check-in.
class TicketScreen extends StatefulWidget {
  const TicketScreen({super.key, required this.eventId});

  final String eventId;

  @override
  State<TicketScreen> createState() => _TicketScreenState();
}

class _TicketScreenState extends State<TicketScreen> {
  late final RegistrationRepository _regRepo;
  late Future<Ticket> _future;
  final bool _bright = true;

  @override
  void initState() {
    super.initState();
    _regRepo = RegistrationRepository();
    _future = _regRepo.getTicket(widget.eventId);
  }

  Future<void> _reload() async {
    setState(() => _future = _regRepo.getTicket(widget.eventId));
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Scaffold(
      appBar: AppBar(title: const Text('My ticket')),
      body: FutureBuilder<Ticket>(
        future: _future,
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return ErrorState(
              message: friendlyError(snapshot.error!),
              onRetry: _reload,
            );
          }
          if (!snapshot.hasData) {
            return const LoadingView(hint: 'Preparing your ticket…');
          }
          final ticket = snapshot.data!;

          return RefreshIndicator(
            onRefresh: _reload,
            child: ListView(
              padding: const EdgeInsets.all(24),
              children: [
                Card(
                  margin: EdgeInsets.zero,
                  child: Padding(
                    padding: const EdgeInsets.all(24),
                    child: Column(
                      children: [
                        Container(
                          padding: const EdgeInsets.all(14),
                          decoration: BoxDecoration(
                            color: _bright
                                ? Colors.white
                                : theme.colorScheme.surfaceContainerHighest,
                            borderRadius: BorderRadius.circular(16),
                          ),
                          child: QrImageView(
                            data: ticket.qrPayload,
                            size: 230,
                            backgroundColor: Colors.transparent,
                          ),
                        ),
                        const SizedBox(height: 16),
                        Text(
                          ticket.checkedIn
                              ? 'Checked in ✓'
                              : 'Show this at the entrance',
                          style: theme.textTheme.titleMedium?.copyWith(
                            fontWeight: FontWeight.w700,
                            color: ticket.checkedIn ? AppTheme.success : null,
                          ),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          'Ticket ID ${ticket.userId.substring(0, 8)}…',
                          style: theme.textTheme.bodySmall?.copyWith(
                              color: theme.colorScheme.onSurfaceVariant),
                        ),
                      ],
                    ),
                  ),
                ),
                const SizedBox(height: 16),
                Text(
                  'How it works',
                  style: theme.textTheme.titleMedium
                      ?.copyWith(fontWeight: FontWeight.w700),
                ),
                const SizedBox(height: 8),
                const ListTile(
                  leading: Icon(Icons.looks_one_rounded),
                  title: Text('Keep this screen handy when you arrive.'),
                  contentPadding: EdgeInsets.zero,
                ),
                const ListTile(
                  leading: Icon(Icons.looks_two_rounded),
                  title: Text('The organizer scans your QR code at the door.'),
                  contentPadding: EdgeInsets.zero,
                ),
                const ListTile(
                  leading: Icon(Icons.looks_3_rounded),
                  title: Text('Each ticket can only be checked in once.'),
                  contentPadding: EdgeInsets.zero,
                ),
                const SizedBox(height: 8),
                OutlinedButton.icon(
                  onPressed: () async {
                    await Clipboard.setData(
                        ClipboardData(text: ticket.qrPayload));
                    if (context.mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('Ticket code copied')),
                      );
                    }
                  },
                  icon: const Icon(Icons.copy_rounded),
                  label: const Text('Copy ticket code'),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
